import { readdirSync, existsSync, readFileSync } from 'node:fs';
import path from 'node:path';

const LINEAGE = [['angular','@angular/core'],['nextjs','next'],['react','react']];
function readJson(p){ try { return JSON.parse(readFileSync(p,'utf8')); } catch { return null; } }
function deps(m){ if(!m) return {}; return { ...(m.dependencies&&typeof m.dependencies==='object'?m.dependencies:{}), ...(m.devDependencies&&typeof m.devDependencies==='object'?m.devDependencies:{}) }; }

function screen(root){
  const dirs=[];
  if(existsSync(path.join(root,'package.json'))) dirs.push('.');
  let entries=[];
  try { entries=readdirSync(root,{withFileTypes:true}).filter(e=>e.isDirectory()).map(e=>e.name).sort(); } catch {}
  for(const n of entries){ if(n==='node_modules'||n==='.git') continue; if(existsSync(path.join(root,n,'package.json'))) dirs.push(n); }
  const out=[];
  for(const d of dirs){
    const m=readJson(path.join(root,d,'package.json'));
    const dd=deps(m);
    const found=LINEAGE.find(([,name])=>Object.hasOwn(dd,name));
    const runtime = found && m && m.dependencies && Object.hasOwn(m.dependencies, found[1]);
    out.push({dir:d, name:m?.name, version:m?.version, license:m?.license, private:m?.private,
      lineage: found?found[0]:'unknown',
      reading: found ? `${d} declares ${found[0]} ${dd[found[1]]} (${runtime?'dependencies':'devDependencies'}.${found[1]})` : `${d} declares no framework this stage reads`,
      lockfiles: ['package-lock.json','npm-shrinkwrap.json','yarn.lock','pnpm-lock.yaml'].filter(f=>existsSync(path.join(root,d,f))),
      workspaces: m?.workspaces ? JSON.stringify(m.workspaces) : undefined,
      pkgMgr: m?.packageManager,
      engines: m?.engines ? JSON.stringify(m.engines) : undefined,
      depCount: Object.keys(dd).length,
    });
  }
  const declaring=out.filter(c=>c.lineage!=='unknown');
  let verdict;
  if(dirs.length===0) verdict='ingest.frontend-root-not-found';
  else if(declaring.length===1) verdict=`READ frontendRoot=${declaring[0].dir}`;
  else if(declaring.length>1) verdict=`ingest.frontend-root-lineage-ambiguous (${declaring.length}: ${declaring.map(c=>c.dir).join(', ')})`;
  else { const subs=out.filter(c=>c.dir!=='.'); verdict = subs.length>1 ? `ingest.frontend-root-ambiguous (${subs.length} subdirs)` : 'ingest.frontend-root-declares-no-framework'; }
  return {root, verdict, candidates: out};
}

for(const root of process.argv.slice(2)){
  const r=screen(root);
  console.log('===== '+r.root);
  console.log('VERDICT: '+r.verdict);
  for(const c of r.candidates) console.log('  - '+JSON.stringify(c));
  // root-level license file first line
  const lf=['LICENSE','LICENSE.md','LICENSE.txt','license'].map(f=>path.join(root,f)).find(p=>existsSync(p));
  if(lf) console.log('  LICENSE file head: '+readFileSync(lf,'utf8').split('\n').slice(0,3).map(s=>s.trim()).filter(Boolean).join(' | '));
}
